{
  "claims": [
    {
      "quote": "Theranos today announced that it has received the U.S. Food and Drug Administration’s clearance of its test system and test for herpes simplex 1 virus IgG.",
      "kind": "specific",
      "why": "A reader can check official FDA records to confirm whether this test system and virus test received clearance."
    },
    {
      "quote": "Specifically, Theranos provided study data from 818 subjects of varying age and ethnicity, demonstrating that its system could be run accurately using only a finger stick as well as a traditional venous draw across large numbers of Theranos devices",
      "kind": "specific",
      "why": "A third party could verify the study participant count and testing data submitted to the regulatory agency."
    },
    {
      "quote": "Theranos’ HSV-1 studies included matrix comparison studies across sixty-nine Theranos devices.",
      "kind": "specific",
      "why": "The exact number of devices used in the matrix comparison studies can be checked against company study documentation."
    },
    {
      "quote": "Theranos’ HSV-1 clinical studies also included sensitivity and specificity studies with hundreds of human samples – both capillary and venous, CDC panel testing – which demonstrated 100% agreement with the results provided by CDC",
      "kind": "specific",
      "why": "A researcher could verify the stated 100% agreement rate with the CDC panel testing results."
    },
    {
      "quote": "Theranos is the first lab to voluntarily commit to submitting all of its LDTs to the FDA for review.",
      "kind": "specific",
      "why": "Regulatory records and public announcements could verify if Theranos was indeed the first laboratory to make this specific commitment."
    },
    {
      "quote": "Theranos’ HSV-1 test costs $9.07 and is one of 153 tests Theranos makes available for less than $10.",
      "kind": "specific",
      "why": "A customer or auditor can check the published price list to verify the exact cost and number of tests under ten dollars."
    },
    {
      "quote": "Theranos, Inc. is a consumer health technology company founded in 2003 by Elizabeth Holmes.",
      "kind": "specific",
      "why": "Corporate registration records can verify the founding year and founder's name."
    },
    {
      "quote": "The FDA’s decision provides independent validation of patented finger stick and venous blood testing technology and the ground breaking Theranos System",
      "kind": "vague",
      "why": "Calling the system ground breaking is subjective marketing language rather than a measurable fact."
    },
    {
      "quote": "FDA’s review process for 510(k) notifications is widely recognized as one of the most rigorous regulatory hurdles in the world for evaluation of the performance, accuracy, and intended use of diagnostic tests.",
      "kind": "vague",
      "why": "The description of the review process as one of the most rigorous in the world is a generalized opinion."
    },
    {
      "quote": "Theranos offers lab tests in convenient locations in its Wellness Centers in Arizona and California, with plans to expand throughout the country.",
      "kind": "vague",
      "why": "The term convenient is an unverifiable subjective claim about the location of the wellness centers."
    }
  ]
}

